import re

def iso_duration_seconds(s):
    # pattern for PnW
    m = re.fullmatch(r'P(\d+(?:\.\d+)?)W', s)
    if m:
        weeks = float(m.group(1))
        return weeks * 7 * 86400
    # pattern for rest
    # P (optional D) T? ...
    # Must start with P
    if not s.startswith('P'):
        raise ValueError
    rest = s[1:]
    # split date part and time part
    # date part: up to optional T
    if 'T' in rest:
        date_part, time_part = rest.split('T', 1)
        if time_part == '':
            raise ValueError
    else:
        date_part, time_part = rest, ''
    # parse date part: optional number + D
    days = 0.0
    if date_part:
        if not date_part.endswith('D'):
            raise ValueError
        num = date_part[:-1]
        if num == '':
            raise ValueError
        if not re.fullmatch(r'\d+(?:\.\d+)?', num):
            raise ValueError
        days = float(num)
    # parse time part: at least one of H M S in order
    hours = minutes = seconds = 0.0
    if time_part:
        # expected pattern: ((\d+\.?\d*)H)?((\d+\.?\d*)M)?((\d+\.?\d*)S)?
        # but ensure order and at least one present
        # we'll parse sequentially
        idx = 0
        # hours
        if idx < len(time_part) and time_part[idx].isdigit():
            match = re.match(r'(\d+(?:\.\d+)?)H', time_part[idx:])
            if match:
                hours = float(match.group(1))
                idx += match.end()
            else:
                raise ValueError
        # minutes
        if idx < len(time_part) and time_part[idx].isdigit():
            match = re.match(r'(\d+(?:\.\d+)?)M', time_part[idx:])
            if match:
                minutes = float(match.group(1))
                idx += match.end()
            else:
                raise ValueError
        # seconds
        if idx < len(time_part) and time_part[idx].isdigit():
            match = re.match(r'(\d+(?:\.\d+)?)S', time_part[idx:])
            if match:
                seconds = float(match.group(1))
                idx += match.end()
            else:
                raise ValueError
        # after parsing, must have consumed all
        if idx != len(time_part):
            raise ValueError
        # ensure at least one component present
        if hours == 0 and minutes == 0 and seconds == 0:
            raise ValueError
    else:
        # no time part, need at least days
        if days == 0:
            raise ValueError
    total_seconds = days*86400 + hours*3600 + minutes*60 + seconds
    return total_seconds

# Test script
def test():
    cases = [
        ("PT0S", 0),
        ("PT1H30M", 5400),
        ("P1DT2H", 93600),
        ("P1W", 604800),
        ("PT0.5S", 0.5),
        ("P2DT3H4M5.25S", 183845.25),
    ]
    for inp, expected in cases:
        got = iso_duration_seconds(inp)
        assert abs(got - expected) < 1e-9, f"{inp}: got {got}, expected {expected}"
    # error cases
    errors = ["", "P", "PT", "1H", "P1H"]
    for inp in errors:
        try:
            iso_duration_seconds(inp)
            assert False, f"{inp} should raise"
        except ValueError:
            pass
    # additional tests
    assert iso_duration_seconds("P0W") == 0
    assert iso_duration_seconds("P0.5W") == 0.5*7*86400
    assert iso_duration_seconds("PD") == ValueError  # no number
    try:
        iso_duration_seconds("PD")
        assert False
    except ValueError:
        pass
    print("ALL TESTS PASSED")

if __name__ == "__main__":
    test()

